from dataclasses import dataclass

@dataclass
class Receipt:
    name: str
    cents: int

    def label(self) -> str:
        return f"{self.name}: ${self.cents / 100:.2f}"

print(Receipt("Pencil", 125).label())

def positive_count(text):
    value = int(text)
    if value <= 0:
        raise ValueError("Enter a positive count")
    return value

for text in ["3", "zero", "-2"]:
    try:
        print(positive_count(text))
    except ValueError as error:
        print("Invalid:", error)
